var keys=Object.keys(phrases).sort(function(a,b){return b.length-a.length});
var wordMap={};Object.keys(words).forEach(function(k){wordMap[k.toLowerCase()]=words[k]});
var wordRE=new RegExp('(?<![\\p{L}])('+Object.keys(words).sort(function(a,b){return b.length-a.length}).map(escapeRE).join('|')+')(?![\\p{L}])','giu');
function escapeRE(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}
function english(s){var t=s.trim();if(exact[t]!==undefined)return s.replace(t,exact[t]);if(exact[s]!==undefined)return exact[s];var slots=[];keys.forEach(function(k){s=s.replace(new RegExp(escapeRE(k),'gi'),function(){var j=slots.push(phrases[k])-1;return '\uE000'+j+'\uE001';});});s=s.replace(wordRE,function(w){return wordMap[w.toLowerCase()]||w});s=s.replace(/\uE000(\d+)\uE001/g,function(_,n){return slots[n]});return s;}
window.toEnglish=english;
var saved=new WeakMap();var attrSaved=new WeakMap();
function translate(root){if(!root)return;var walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);var node;while(node=walker.nextNode()){var parent=node.parentElement;if(!parent||parent.closest('script,style,textarea,option[data-fixed],.mybr,.note,#language'))continue;var prev=saved.get(node);var raw=prev && node.nodeValue===prev.out?prev.raw:node.nodeValue;var out=lang==='en'?english(raw):raw;saved.set(node,{raw:raw,out:out});if(node.nodeValue!==out)node.nodeValue=out;}root.querySelectorAll('[placeholder],[aria-label],[alt],optgroup[label]').forEach(function(el){var old=attrSaved.get(el)||{};['placeholder','aria-label','alt','label'].forEach(function(a){if(!el.hasAttribute(a))return;var v=el.getAttribute(a),p=old[a],raw=p&&v===p.out?p.raw:v;var out=lang==='en'?english(raw):raw;old[a]={raw:raw,out:out};if(v!==out)el.setAttribute(a,out)});attrSaved.set(el,old);});}
window.addEventListener('DOMContentLoaded',function(){var select=document.getElementById('language');select.value=lang;document.documentElement.lang=lang;function run(){observer.disconnect();translate(document.body);observer.observe(document.body,{subtree:true,childList:true,characterData:true});}var observer=new MutationObserver(run);run();select.onchange=function(){lang=select.value;document.documentElement.lang=lang;try{localStorage.setItem('comptoir-language',lang)}catch(e){}run();};});
